cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void conv_transpose2d_fp16_kernel(
    const scalar_t* __restrict__ input,      // [N, C_in, H_in, W_in]
    const scalar_t* __restrict__ weight,     // [C_in/groups, C_out, K, K]
    const scalar_t* __restrict__ bias,       // [C_out] or nullptr
    scalar_t* __restrict__ output,           // [N, C_out, H_out, W_out]
    const int N,
    const int C_in,
    const int H_in,
    const int W_in,
    const int C_out,
    const int K,
    const int stride,
    const int padding,
    const int output_padding,
    const int groups)
{
    // output index
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;   // width
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;   // height
    int c_out = blockIdx.z % C_out;                      // output channel
    int n     = blockIdx.z / C_out;                      // batch index

    // compute output dimensions
    const int H_out = (H_in - 1) * stride - 2 * padding + K + output_padding;
    const int W_out = (W_in - 1) * stride - 2 * padding + K + output_padding;

    if (n >= N || c_out >= C_out || h_out >= H_out || w_out >= W_out) return;

    // accumulate in float for better precision
    float acc = 0.0f;

    // Determine which group this output channel belongs to
    const int group_id = c_out / (C_out / groups);
    const int c_out_in_group = c_out % (C_out / groups);
    const int C_in_per_group = C_in / groups;

    // Loop over input channels belonging to same group
    for (int ic = 0; ic < C_in_per_group; ++ic) {
        int c_in = group_id * C_in_per_group + ic;   // actual input channel index

        // Loop over kernel spatial dimensions
        for (int kh = 0; kh < K; ++kh) {
            // Compute corresponding input height index
            int h_in = (h_out + padding - kh);
            if (h_in % stride != 0) continue;
            h_in = h_in / stride;
            if (h_in < 0 || h_in >= H_in) continue;

            for (int kw = 0; kw < K; ++kw) {
                int w_in = (w_out + padding - kw);
                if (w_in % stride != 0) continue;
                w_in = w_in / stride;
                if (w_in < 0 || w_in >= W_in) continue;

                // Offsets
                const int input_idx  = ((n * C_in + c_in) * H_in + h_in) * W_in + w_in;
                const int weight_idx = ((ic) * (C_out / groups) + c_out_in_group) * K * K
                                       + kh * K + kw;

                // Load half, convert to float
                float in_val = __half2float(input[input_idx]);
                float w_val  = __half2float(weight[weight_idx]);

                acc += in_val * w_val;
            }
        }
    }

    // Add bias if present
    if (bias != nullptr) {
        acc += __half2float(bias[c_out]);
    }

    // Write result back as half
    output[((n * C_out + c_out) * H_out + h_out) * W_out + w_out] = __float2half(acc);
}
'''

