    const torch::Tensor& input,
    const torch::Tensor& weight,
    const torch::Tensor& bias,
    torch::Tensor& output,
    int stride,
    int padding,
    int output_padding,
    int groups)
{
    const int N   = input.size(0);
    const int C_in= input.size(1);
    const int H_in= input.size(2);
    const int W_in= input.size(3);
    const int C_out= weight.size(1) * groups; // weight shape [C_in_per_group, C_out_per_group, K, K]
    const int K   = weight.size(2);
    const int H_out = (H_in - 1) * stride - 2 * padding + K + output_padding;
    const int W_out = (W_in - 1) * stride - 2 * padding + K + output_padding;

    const dim3 block(16, 16);
    const dim3 grid(
        (W_out + block.x - 1) / block.x,
        (H_out + block.y - 1) / block.y,
        N * C_out
    );

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "conv_transpose2d_fp16_kernel", ([&] {
        conv_transpose2d_fp16_kernel<scalar_t><<<grid, block>>>(
            input.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            bias.defined() ? bias.data_ptr<scalar_t>() : nullptr,
            output.data_ptr<scalar_t>(),
            N,
            C_in,
            H_in,
            W_in,
            C_out,
            K,
            stride,
            padding,
            output_padding,
            groups);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in conv_transpose2d_fp16_kernel: %s\\n", cudaGetErrorString(err));
    }
}
'''

