                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        # weight shape: [C_in/groups, C_out/groups, K, K]
        weight_shape = (in_channels // groups, out_channels // groups, kernel_size, kernel_size)
        self.weight = nn.Parameter(torch.empty(weight_shape, dtype=torch.float16, device='cuda'))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels, dtype=torch.float16, device='cuda'))
            fan_in = in_channels * kernel_size * kernel_size
            bound = 1 / math.sqrt(fan_in)
            torch.nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16 and CUDA
        x = x.to(dtype=torch.float16, device='cuda')
        weight = self.weight

        # Output dimensions
        H_in, W_in = x.shape[2], x.shape[3]
        H_out = (H_in - 1) * self.stride - 2 * self.padding + self.kernel_size + self.output_padding
        W_out = (W_in - 1) * self.stride - 2 * self.padding + self.kernel_size + self.output_padding

        out = torch.empty((x.size(0), self.out_channels, H_out, W_out),
                          dtype=torch.float16, device='cuda')
        out.zero_()

        module.forward(x, weight, self.bias if self.bias is not None else torch.tensor([]), out,
                       self.stride, self.padding, self.output_padding, self.groups)
        return out

# ----------------------------------------------------------------------
# Example usage (mirrors the reference test)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    import math
    batch_size = 8
    in_channels = 64
    out_channels = 64
    kernel_size = 3
    height = 1024
